289	        if (isBlank(fields.getLastName())) {
290	            missing.add("lastName");
291	        }
292	        if (isBlank(normalizeAddress(fields.getAddress()))) {
293	            missing.add("address");
294	        }
295	        if (isBlank(fields.getCity())) {
296	            missing.add("city");
297	        }
298	        if (isBlank(fields.getTelephone())) {
