310	    /**
311	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
312	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
313	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
314	     */
315	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
316	        "NSW", new int[] {2000, 2099},
317	        "VIC", new int[] {3000, 3099},
318	        "QLD", new int[] {4000, 4099});
319	
320	    /**
321	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
322	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
323	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
324	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
325	     *
326	     * @param postcode the submitted postcode, or {@code null} when omitted
327	     * @param city the owner's city, used to derive the region whose range constrains the postcode
328	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
329	     *                                  city's region
330	     */
331	    private void validatePostcode(String postcode, String city) {
332	        if (postcode == null) {
333	            return;
334	        }
335	        if (!postcode.matches("[0-9]{4}")) {
336	            throw new InvalidPostcodeException(postcode);
337	        }
338	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
339	        if (range == null) {
340	            return;
341	        }
342	        int value = Integer.parseInt(postcode);
343	        if (value < range[0] || value > range[1]) {
344	            throw new InvalidPostcodeException(postcode);
345	        }
346	    }
