348	    /**
349	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
350	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
351	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
352	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
353	     * <p>
354	     * Where a per-country rule is defined the national-number length is validated against the country
355	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
356	     * requires exactly 10.
357	     *
358	     * @param telephone the raw telephone value from the request
359	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
360	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
361	     */
362	    private String normalizeTelephone(String telephone) {
363	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
364	        String digits;
365	        if (cleaned.startsWith("+")) {
366	            digits = cleaned.substring(1);
367	        } else {
368	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
369	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
370	            digits = "61" + national;
371	        }
372	        if (!digits.matches("[0-9]{8,15}")) {
373	            throw new InvalidTelephoneException(cleaned);
374	        }
375	        // Validate the national-number length against the country code where a rule is defined.
376	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
377	            throw new InvalidTelephoneException(cleaned);
378	        }
379	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
380	            throw new InvalidTelephoneException(cleaned);
381	        }
382	        return "+" + digits;
383	    }
384	
385	    /**
386	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
387	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
388	     * lower-cased.
389	     *
390	     * @param email the raw email value from the request, or {@code null} if omitted
391	     * @return the lower-cased email, or {@code null} if none was supplied
392	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
393	     */
394	    private String normalizeEmail(String email) {
395	        if (email == null) {
396	            return null;
397	        }
398	        String trimmed = email.strip();
399	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
400	            throw new InvalidEmailException(email);
401	        }
402	        String normalized = trimmed.toLowerCase(Locale.ROOT);
403	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
404	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
405	            throw new DisposableEmailDomainException(domain);
406	        }
407	        return normalized;
408	    }
409	
410	    /**
411	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
412	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
413	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
414	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
415	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
416	     *
417	     * @param address the raw address value from the request (may be {@code null})
418	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
419	     */
420	    private String normalizeAddress(String address) {
421	        if (address == null) {
422	            return "";
423	        }
424	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
425	        if (collapsed.isEmpty()) {
426	            return "";
427	        }
428	        String[] tokens = collapsed.split(" ");
429	        StringBuilder sb = new StringBuilder(collapsed.length());
430	        for (int i = 0; i < tokens.length; i++) {
431	            if (i > 0) {
432	                sb.append(' ');
433	            }
434	            sb.append(expandAddressAbbreviation(tokens[i]));
435	        }
436	        return sb.toString();
437	    }
438	
439	    /**
440	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
441	     * returns the token unchanged when it is not a recognised abbreviation.
442	     *
443	     * @param token an upper-cased whole-word address token
444	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
445	     */
446	    private String expandAddressAbbreviation(String token) {
447	        return switch (token) {
448	            case "ST" -> "STREET";
449	            case "RD" -> "ROAD";
450	            case "AVE" -> "AVENUE";
451	            default -> token;
452	        };
453	    }
454	
455	    /**
456	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
457	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
458	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
459	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
460	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}).
461	     * <p>
462	     * Should the computed code collide with an existing owner's {@code customerCode}, it is de-duplicated
463	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not already
464	     * held by any existing owner; the de-duplicated code is returned.
465	     *
466	     * @param owner the owner being created, with normalized telephone and postcode already set
467	     * @return the assigned, collision-free customer code
468	     */
469	    private String generateCustomerCode(Owner owner) {
470	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
471	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
472	            .substring(0, 8).toUpperCase(Locale.ROOT);
473	        String base = region + "-" + hash8;
474	        Set<String> existing = this.clinicService.findAllOwners().stream()
475	            .map(Owner::getCustomerCode)
476	            .filter(code -> code != null)
477	            .collect(java.util.stream.Collectors.toSet());
478	        if (!existing.contains(base)) {
479	            return base;
480	        }
481	        int n = 2;
482	        while (existing.contains(base + "-" + n)) {
483	            n++;
484	        }
485	        return base + "-" + n;
486	    }
487	
488	    /**
489	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
490	     *
491	     * @param value the value to hash
492	     * @return the 64-character lower-case hex SHA-256 digest
493	     */
494	    private String sha256Hex(String value) {
495	        try {
496	            byte[] digest = MessageDigest.getInstance("SHA-256")
497	                .digest(value.getBytes(StandardCharsets.UTF_8));
498	            StringBuilder sb = new StringBuilder(digest.length * 2);
499	            for (byte b : digest) {
500	                sb.append(String.format("%02x", b));
501	            }
502	            return sb.toString();
503	        } catch (NoSuchAlgorithmException e) {
504	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
505	        }
506	    }
