508	    /**
509	     * Counts how many existing owners already share the given first name and last name, compared
510	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
511	     * owner being created.
512	     *
513	     * @param firstName the first name of the owner being created
514	     * @param lastName the last name of the owner being created
515	     * @return the number of existing owners with the same first and last name (case-insensitively)
516	     */
517	    private int countNamesakes(String firstName, String lastName) {
518	        return (int) this.clinicService.findAllOwners().stream()
519	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
520	                && lastName.equalsIgnoreCase(existing.getLastName()))
521	            .count();
522	    }
