524	    /**
525	     * Computes the size of the owner's household: the number of existing owners already sharing the given
526	     * {@code householdId} plus the owner being created itself. The existing count is taken before the new
527	     * owner is persisted, so adding one for the owner yields the household's total membership including it
528	     * (e.g. two existing members give a household size of 3 for the third member). Households are keyed on
529	     * the deterministic {@code householdId} (derived from last name and postcode).
530	     *
531	     * @param householdId the computed household identifier of the owner being created
532	     * @return the household size including the owner being created (at least 1)
533	     */
534	    private int countHouseholdSize(String householdId) {
535	        long existing = this.clinicService.findAllOwners().stream()
536	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
537	            .count();
538	        return (int) existing + 1;
539	    }
