541	    /**
542	     * The maximum number of owners permitted in a single city. A create request whose city already
543	     * holds this many owners is rejected.
544	     */
545	    private static final int CITY_OWNER_LIMIT = 50;
546	
547	    /**
548	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
549	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
550	     * differing only in the casing of their city share one capacity pool. The count is taken before the
551	     * new owner is persisted, so it excludes the owner being created.
552	     *
553	     * @param city the city of the owner being created
554	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
555	     */
556	    private void rejectCityAtCapacity(String city) {
557	        long existing = this.clinicService.findAllOwners().stream()
558	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
559	            .count();
560	        if (existing >= CITY_OWNER_LIMIT) {
561	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
562	        }
563	    }
564	
565	    /**
566	     * The maximum number of owners permitted to be created in a single day. A create request whose
567	     * registration date already holds this many owners is rejected.
568	     */
569	    private static final int DAILY_OWNER_LIMIT = 100;
570	
571	    /**
572	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
573	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
574	     * persisted, so it excludes the owner being created.
575	     *
576	     * @param registrationDate the registration date of the owner being created
577	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
578	     */
579	    /**
580	     * Adjusts an effective registration date so that it always falls on a business day. When the given
581	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
582	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
583	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
584	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
585	     * business-day-adjusted date.
586	     *
587	     * @param date the effective registration date, supplied or defaulted
588	     * @return the same date when it is a weekday, otherwise the next Monday
589	     */
590	    private LocalDate rollToBusinessDay(LocalDate date) {
591	        DayOfWeek day = date.getDayOfWeek();
592	        if (day == DayOfWeek.SATURDAY) {
593	            return date.plusDays(2);
594	        }
595	        if (day == DayOfWeek.SUNDAY) {
596	            return date.plusDays(1);
597	        }
598	        return date;
599	    }
600	
601	    /**
602	     * The number of owners that must already exist for a given day before a further create is flagged as a
603	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
604	     * the created owner carries {@code bulkSignupWarning = true}.
605	     */
606	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
607	
608	    /**
609	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
610	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
611	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
612	     * the daily create-limit rule's accumulation path.
613	     *
614	     * @param registrationDate the registration date of the owner being created
615	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
616	     */
617	    private boolean isBulkSignupDay(LocalDate registrationDate) {
618	        long existing = this.clinicService.findAllOwners().stream()
619	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
620	            .count();
621	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
622	    }
623	
624	    /**
625	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
626	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
627	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
628	     * made against the supplied value before any business-day adjustment.
629	     *
630	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
631	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
632	     */
633	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
634	        if (registrationDate == null) {
635	            return;
636	        }
637	        LocalDate today = LocalDate.now();
638	        if (registrationDate.isAfter(today)) {
639	            throw new FutureRegistrationDateException(registrationDate, today);
640	        }
641	    }
642	
643	    private void rejectDailyLimitReached(LocalDate registrationDate) {
644	        long existing = this.clinicService.findAllOwners().stream()
645	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
646	            .count();
647	        if (existing >= DAILY_OWNER_LIMIT) {
648	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
649	        }
650	    }
651	
652	    /**
653	     * Rejects a create request whose owner collides with an existing owner on the single derived
654	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
655	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
656	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
657	     * household (same {@code householdId}) with different telephones have different keys and are both
658	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} has already
659	     * been computed (deterministically from the last name and postcode) before this check runs, so the
660	     * key compared here is the same one that is later returned.
661	     *
662	     * @param owner the owner being created, with normalized fields and its computed {@code householdId} set
663	     * @throws DuplicateIdentityException if an existing owner has the same identity key
664	     */
665	    private void rejectDuplicateIdentity(Owner owner) {
666	        String key = identityKey(owner);
667	        boolean taken = this.clinicService.findAllOwners().stream()
668	            .anyMatch(existing -> key.equals(identityKey(existing)));
669	        if (taken) {
670	            throw new DuplicateIdentityException(key);
671	        }
672	    }
673	
674	    /**
675	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
676	     * while not a hard {@code identityKey} duplicate (that stronger check has already run), shares this
677	     * owner's last name (compared case-insensitively) and exact postcode but carries a different normalized
678	     * telephone. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
679	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
680	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
681	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
682	     * <p>
683	     * A declared household member ({@code sharesHousehold}) is never flagged: sharing a last name and
684	     * postcode is now exactly the household key, so such an owner is a known household member rather than
685	     * a suspected duplicate.
686	     *
687	     * @param owner the owner being created, with normalized telephone and validated postcode already set
688	     * @param sharesHousehold whether the create declared the owner a household member
689	     */
690	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
691	        Integer matchId = null;
692	        if (!sharesHousehold && owner.getPostcode() != null) {
693	            matchId = this.clinicService.findAllOwners().stream()
694	                .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
695	                    && owner.getPostcode().equals(existing.getPostcode())
696	                    && !telephonesEqual(owner.getTelephone(), existing.getTelephone()))
697	                .map(Owner::getId)
698	                .filter(id -> id != null)
699	                .min(Comparator.naturalOrder())
700	                .orElse(null);
701	        }
702	        owner.setPossibleDuplicate(matchId != null);
703	        owner.setPossibleDuplicateOf(matchId);
704	    }
705	
706	    private boolean telephonesEqual(String a, String b) {
707	        return a == null ? b == null : a.equals(b);
708	    }
709	
710	    /**
711	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
712	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
713	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
714	     * Telephone and email are stored already normalized, so the stored values are used directly.
715	     *
716	     * @param owner the owner whose identity key is being derived
717	     * @return the owner's identity key
718	     */
719	    private String identityKey(Owner owner) {
720	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
721	        String email = owner.getEmail() == null ? "" : owner.getEmail();
722	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
723	        return telephone + "|" + email + "|" + householdId;
724	    }
725	
726	    /**
727	     * Computes the owner's deterministic {@code householdId}: the first 12 hex characters of the SHA-256
728	     * digest of {@code '<normalizedLastName>|<postcode>'}, where the last name is normalized with
729	     * {@link #normalizeForComparison} and an absent postcode contributes an empty string. Because the
730	     * identifier is a pure function of last name and postcode, any two owners sharing those values share
731	     * the household automatically, with no cross-owner mutation. The value is assigned to every owner,
732	     * whether or not {@code sharesHousehold} was requested.
733	     *
734	     * @param owner the owner being created, with its validated postcode already set
735	     * @return the deterministic household identifier
736	     */
737	    private String computeHouseholdId(Owner owner) {
738	        String normalizedLastName = normalizeForComparison(owner.getLastName());
739	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
740	        return sha256Hex(normalizedLastName + "|" + postcode).substring(0, 12);
741	    }
742	
743	    /**
744	     * Rejects a create request whose owner would join an existing household without declaring it. The
745	     * household is keyed on the computed {@code householdId} (derived from last name and postcode), so any
746	     * existing owner sharing that identifier is already a member of the same household; a further owner is a
747	     * household duplicate. The check is bypassed when the request opted in via {@code sharesHousehold}, in
748	     * which case the owner is created as a declared household member. The (stronger) exact identity-key
749	     * check has already run, so a full duplicate is rejected regardless of {@code sharesHousehold}.
750	     *
751	     * @param owner the owner being created, with its computed {@code householdId} already assigned
752	     * @throws HouseholdDuplicateException if an existing owner already shares the household
753	     */
754	    private void rejectHouseholdDuplicate(Owner owner) {
755	        String householdId = owner.getHouseholdId();
756	        boolean shared = this.clinicService.findAllOwners().stream()
757	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
758	        if (shared) {
759	            throw new HouseholdDuplicateException(householdId);
760	        }
761	    }
762	
763	    /**
764	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
765	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
766	     * lower-cased.
767	     *
768	     * @param value the raw value to normalize (may be {@code null})
769	     * @return the normalized value, or an empty string when {@code value} is {@code null}
770	     */
771	    private String normalizeForComparison(String value) {
772	        if (value == null) {
773	            return "";
774	        }
775	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
776	    }
777	}
